SELECT CASE WHEN event_type IN ('click', 'add_to_cart') THEN 'priority' ELSE 'other' END AS event_type_group, event_type, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range FROM web_events GROUP BY ROLLUP(CASE WHEN event_type IN ('click', 'add_to_cart') THEN 'priority' ELSE 'other' END, event_type) ORDER BY event_type DESC;
